import java.util.*;
public class Main {
    static int[] par, rank_;
    static int find(int x){while(par[x]!=x){par[x]=par[par[x]];x=par[x];}return x;}
    static void unite(int a,int b){
        int ra=find(a),rb=find(b);
        if(ra==rb)return;
        if(rank_[ra]<rank_[rb]){int t=ra;ra=rb;rb=t;}
        par[rb]=ra;
        if(rank_[ra]==rank_[rb])rank_[ra]++;
    }
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt(),m=sc.nextInt();
        par=new int[n+1];rank_=new int[n+1];
        for(int i=0;i<=n;i++)par[i]=i;
        for(int i=0;i<m;i++)unite(sc.nextInt(),sc.nextInt());
        int q=sc.nextInt();
        while(q-->0){
            int u=sc.nextInt(),v=sc.nextInt();
            System.out.println(find(u)==find(v)?"YES":"NO");
        }
    }
}
